  ACT['crm-info-save'] = () => { const w = document.getElementById('crmInfo'); if (!w) return; const m = M(w.dataset.v); if (!m) return; const x = info(m); const n = fv(w, 'n'), ph = fv(w, 'ph'), vh = +fv(w, 'vh') || 0; if (!n) { toast('이름을 입력해 주십시오.', 'warn'); return; } if (!phoneOk(ph)) { toast('연락처 형식을 확인해 주십시오.', 'warn'); return; } if (vh < 0) { toast('차량비를 확인해 주십시오.', 'warn'); return; } m.name = n; m.phone = ph; Object.assign(x, { school: fv(w, 'sc'), gy: fv(w, 'gy'), hope: fv(w, 'hp'), regAt: fv(w, 'rg') || regAt(m), payDay: +fv(w, 'pd') || 0, vehicle: vh, disc: fv(w, 'dc'), memo: fv(w, 'mm') }); logAudit(`원생 정보 수정 — ${m.sid}`); save(); render(); toast('저장했습니다.', 'ok'); };
