  const setStatus = (ids, act, d, r) => ids.forEach(id => { const m = M(id); if (!m) return; const x = info(m); x.st = act; if (act === '퇴원') { x.outAt = d; x.outReason = r; S.classes.forEach(c => { if ((c.learners || []).includes(id)) { c.learners = c.learners.filter(v => v !== id); addHist(id, '퇴원', { cls: c.id, at: d, memo: r }); } }); if (!HIST().some(h => h.who === id && h.kind === '퇴원' && h.at === d)) addHist(id, '퇴원', { at: d, memo: r }); } else { if (act === '재원') { delete x.outAt; delete x.outReason; } addHist(id, act === '재원' ? '복원' : act, { at: d, memo: r }); } });
