  function importCsv(txt) { const lines = String(txt || '').replace(/^﻿/, '').split(/\r?\n/).filter(x => x.trim()); if (!lines.length) { toast('등록할 내용이 없습니다.', 'warn'); return false; } const rows = lines.map(parseLine).filter(r => r[0] !== '이름'); let ok = 0; const bad = []; rows.forEach((r, i) => { const [n, sc, gy, ph, pn, pp, cn] = r; if (!n || !phoneOk(ph) || !phoneOk(pp) || (gy && !GRADES.includes(gy))) { bad.push(i + 1); return; } if (STUDENTS().some(m => m.name === n && (pp ? parents(m.id).some(p => digits(p.phone) === digits(pp)) : !parents(m.id).length))) { bad.push(i + 1); return; } const m = newStudent({ name: n, school: sc, gy, phone: ph, consent: true }); if (pn || pp) addParent(m.id, pn, pp, ''); const c = cn && myCls().find(x => x.name === cn); if (c) enrollTo(c, m.id); addHist(m.id, '입학', { cls: c ? c.id : '' }); autoSib(m); ok++; }); logAudit(`원생 일괄 등록 — ${ok}명`); save(); render(); toast(`${ok}명을 등록했습니다.${bad.length ? ` 제외 ${bad.length}행(${bad.slice(0, 5).join(', ')}행 등)` : ''}`, bad.length ? 'warn' : 'ok'); return true; }
