  function attDay() { const d = curD(); const U = dayUnits(d); const noSched = myCls().filter(c => !W2.hasUnits(c)); let und = 0; U.forEach(({ c, u }) => { if (!dxRead(c, u.id).closed) und += rollOf(c).filter(m => !W2.get(c, u.id, m.id)).length; }); return `<div class="bar2 k-date"><button class="btn sm" data-act="crm-day" data-v="${addDays(d, -1)}" aria-label="전날">‹</button><input type="date" value="${esc(d)}" aria-label="날짜" data-chg="crm-dd"><button class="btn sm" data-act="crm-day" data-v="${addDays(d, 1)}" aria-label="다음 날">›</button>${d === today() ? '' : `<button class="btn sm" data-act="crm-day" data-v="${today()}">오늘</button>`}<span class="mini">수업 ${U.length}개 · 미입력 ${und}명</span></div>${U.length ? U.map(attClass).join('') : `<div class="empty">${esc(d)}에 예정된 수업이 없습니다.</div>`}${noSched.length ? `<p class="mini">일정이 없는 수업 ${noSched.length}개는 표시되지 않습니다. 수업에서 회차를 등록해 주십시오.</p>` : ''}`; }
  function attClass({ c, u }) { const d = dxRead(c, u.id); const L = rollOf(c); const mk = (c.makeups || []).filter(x => x.st !== '완료'); const undone = L.filter(m => !W2.get(c, u.id, m.id)).length; const K = `data-c="${esc(c.id)}" data-k="${esc(u.id)}"`;
    return `<section class="card k-attc"><div class="ch"><b>${esc(c.name)}</b><small>${esc(u.from || '')}${u.to ? '~' + esc(u.to) : ''} · ${L.length}명${d.closed ? ' · 휴강' : ` · 미입력 ${undone}명`}</small>${d.closed || !undone ? '' : `<button class="btn pri sm" data-act="crm-att-all" ${K}>미입력 전체 출석</button>`}<button class="btn sm" data-act="crm-att-close" ${K}>${d.closed ? '휴강 취소' : '휴강'}</button></div>${d.closed ? '<p class="mini">휴강 처리한 회차는 출석률 계산에서 제외합니다.</p>' : `${table(['이름', '출결', '사유', ''], L.map(m => { const v = W2.get(c, u.id, m.id); const r = d.rows[m.id] || {}; const a = `${K} data-m="${esc(m.id)}"`; return [esc(m.name), `<span class="k-st">${W2.ST.map(s => `<button class="${v === s ? 'on ' + (W2.TONE[s] || '') : ''}" aria-pressed="${v === s}" data-act="crm-att" ${a} data-v="${s}">${s}</button>`).join('')}</span>`, `<input maxlength="60" aria-label="${esc(m.name)} 출결 사유" value="${esc(r.reason || '')}" data-chg="crm-row" ${a} data-f="reason">`, `<button class="btn sm" data-act="crm-att-more" ${a}>상세</button>`]; }), '출결 대상 원생이 없습니다.')}<div class="bar2"><button class="btn sm" data-act="crm-cl-more" ${K}>진도 · 과제${d.prog || d.hw ? ' 입력됨' : ' 입력'}</button></div>`}${mk.length ? `<h4 class="k-h">예정 보강</h4>${table(['원생', '일시', '메모', ''], mk.map(x => [mn(x.mid), esc(`${x.date} ${x.time || ''}`), esc(x.memo || '—'), `<button class="btn sm" data-act="crm-mk-done" data-c="${esc(c.id)}" data-v="${esc(x.id)}">완료</button>`]))}` : ''}</section>`; }
  ACT['crm-att-more'] = el => { const c = C(el.dataset.c); if (!canC(c)) return; const k = el.dataset.k, mid = el.dataset.m; const tm = (c.attT[k] || {})[mid] || {}; const r = dxRead(c, k).rows[mid] || {}; modal(`출결 상세 — ${M(mid)?.name || ''}`, `<div class="k-grid"><label class="fl">등원<input type="time" name="i" value="${esc(tm.in || '')}"></label><label class="fl">하원<input type="time" name="o" value="${esc(tm.out || '')}"></label></div><label class="ckl"><input type="checkbox" name="h" ${r.hw ? 'checked' : ''}> 과제 제출</label><label class="fl">메모<input name="m" maxlength="100" value="${esc(r.memo || '')}"></label>`, [{ id: 'mk', label: '보강 등록', run: () => { setTimeout(() => ACT['crm-mk']({ dataset: { c: c.id, k, m: mid } })); } }, { id: 'c', label: '취소' }, { id: 'ok', label: '저장', kind: 'pri', run: w => { c.attT[k] = c.attT[k] || {}; const T = c.attT[k][mid] = c.attT[k][mid] || {}; T.in = fv(w, 'i'); T.out = fv(w, 'o'); const D = dxWrite(c, k); const R = D.rows[mid] = D.rows[mid] || {}; R.hw = !!fv(w, 'h'); R.memo = fv(w, 'm'); save(); render(); } }]); };
  ACT['crm-cl-more'] = el => { const c = C(el.dataset.c); if (!canC(c)) return; const k = el.dataset.k; const d = dxRead(c, k); modal(`진도 · 과제 — ${c.name}`, `<label class="fl">진도<input name="p" maxlength="100" value="${esc(d.prog)}"></label><label class="fl">과제<input name="h" maxlength="100" value="${esc(d.hw)}"></label>`, [{ id: 'c', label: '취소' }, { id: 'ok', label: '저장', kind: 'pri', run: w => { const D = dxWrite(c, k); D.prog = fv(w, 'p'); D.hw = fv(w, 'h'); save(); render(); } }]); };
  const canC = c => !!c && myCls().includes(c);
  ACT['crm-att'] = el => { const c = C(el.dataset.c); if (!canC(c)) return; const k = el.dataset.k, mid = el.dataset.m; const v = W2.get(c, k, mid) === el.dataset.v ? '' : el.dataset.v; W2.set(c, k, mid, v); if (v) { const tm = c.attT[k][mid] = c.attT[k][mid] || {}; if (['출석', '지각'].includes(v) && !tm.in && curD() === today()) tm.in = w2Now(); } logAudit(`출결 ${v || '취소'} — ${c.name}`); save(); render(); };
