  ACT['crm-att-close'] = el => { const c = C(el.dataset.c); if (!canC(c)) return; const k = el.dataset.k; const d = dxWrite(c, k); d.closed = !d.closed; (c.learners || []).forEach(id => { c.enr = c.enr || {}; const e = c.enr[id] = c.enr[id] || { at: c.start || today(), ex: [] }; const X = new Set(e.ex || []); if (d.closed) X.add(k); else X.delete(k); e.ex = [...X]; if (d.closed && W2.get(c, k, id)) W2.set(c, k, id, '', 'admin', true); W2.recalc(c, id); }); W2.notify(c.learners.slice(), d.closed ? '휴강 안내' : '휴강 취소 안내', `[${S.org.name}] 「${c.name}」 ${W2.uLabel(c, k)} 수업이 ${d.closed ? '휴강되었습니다' : '정상 진행됩니다'}.`); logAudit(`${d.closed ? '휴강' : '휴강 취소'} — ${c.name}`); save(); render(); if (S.me.role === 'teacher') toast('휴강 안내는 운영자에게 요청해 주십시오.', 'warn'); };
  ACT['crm-row'] = el => { const c = C(el.dataset.c); if (!canC(c)) return; const d = dxWrite(c, el.dataset.k); const r = d.rows[el.dataset.m] = d.rows[el.dataset.m] || {}; r[el.dataset.f] = el.type === 'checkbox' ? el.checked : el.value.trim(); save(); };
  ACT['crm-mk'] = el => { const c = C(el.dataset.c), mid = el.dataset.m; if (!canC(c)) return; modal(`보강 등록 — ${M(mid)?.name || ''}`, `<label class="fl">일자<input name="d" type="date" value="${addDays(today(), 1)}"></label><label class="fl">시간<input name="t" type="time"></label><label class="fl">메모<input name="m" maxlength="100"></label>`, [{ id: 'c', label: '취소' }, { id: 'ok', label: '등록', kind: 'pri', run: w => { const d = fv(w, 'd'); if (!d) { toast('일자를 입력해 주십시오.', 'warn'); return false; } (c.makeups = c.makeups || []).push({ id: uid('mk'), mid, from: el.dataset.k, date: d, time: fv(w, 't'), memo: fv(w, 'm'), st: '예정' }); W2.notify([mid], '보강 안내', `[${S.org.name}] 「${c.name}」 보강이 ${d} ${fv(w, 't')}에 예정되었습니다.`); logAudit(`보강 등록 — ${c.name}`); save(); render(); } }]); };
