  ACT['crm-ex-new'] = () => { const cf = CFG(); const L = myCls(); modal('시험 등록', `<label class="fl">수업<select name="c">${opt(L.map(x => [x.id, x.name]), UI.crmEC)}</select></label><label class="fl">시험명<input name="n" maxlength="40"></label><label class="fl">종류<select name="k">${opt(cf.examKinds)}</select></label><label class="fl">시험일<input name="d" type="date" value="${today()}"></label><label class="fl">만점<input name="m" type="number" min="1" max="1000" value="100"></label>`, [{ id: 'c', label: '취소' }, { id: 'ok', label: '등록', kind: 'pri', run: w => { const c = C(fv(w, 'c')), n = fv(w, 'n'), mx = +fv(w, 'm'); if (!canC(c)) { toast('수업을 확인해 주십시오.', 'warn'); return false; } if (!n) { toast('시험명을 입력해 주십시오.', 'warn'); return false; } if (!(mx > 0)) { toast('만점을 확인해 주십시오.', 'warn'); return false; } const e = { id: uid('ex'), name: n, kind: fv(w, 'k'), date: fv(w, 'd') || today(), max: mx, scores: {} }; EXS(c).push(e); UI.crmEC = c.id; UI.crmE = e.id; logAudit(`시험 등록 — ${c.name} ${n}`); save(); render(); } }]); };
  const exFind = el => { const c = C(el.dataset.c); return canC(c) ? { c, e: EXS(c).find(x => x.id === (el.dataset.e || el.dataset.v)) } : {}; };
  ACT['crm-sc'] = el => { const { e } = exFind(el); if (!e) return; const raw = el.value.trim(); const s = e.scores[el.dataset.m] = e.scores[el.dataset.m] || {}; if (raw === '') { delete s.v; if (!s.absent) delete e.scores[el.dataset.m]; save(); render(); return; } const v = +raw; if (!(v >= 0 && v <= +e.max)) { toast(`점수는 0~${+e.max} 사이로 입력해 주십시오.`, 'warn'); render(); return; } s.v = v; save(); render(); };
