  const dailyFacts = d => { const U = dayUnits(d); let need = 0, marked = 0, absent = 0, closed = 0; const absNames = []; U.forEach(({ c, u }) => { if (dxRead(c, u.id).closed) { closed++; return; } rollOf(c).forEach(m => { need++; const v = W2.get(c, u.id, m.id); if (v) marked++; if (v === '결석') { absent++; absNames.push(m.name); } }); }); const pays = allPays().filter(p => p.at === d); const un = (S.bills || []).filter(billOpen); const lateB = un.filter(b => b.due && b.due < d); const cf = CFG(); const lim = addDays(d, -(+cf.csDays)); const last = {}; (S.consults || []).forEach(c => { const a = String(c.at).slice(0, 10); if (!last[c.who] || last[c.who] < a) last[c.who] = a; }); return { U, need, marked, absent, absNames, closed, income: pays.reduce((a, p) => a + p.amt, 0), un: un.reduce((a, b) => a + billBal(b), 0), lateN: lateB.length, cs: (S.consults || []).filter(c => String(c.at).slice(0, 10) === d).length, newN: HIST().filter(h => h.kind === '입학' && h.at === d).length, outN: new Set(HIST().filter(h => h.kind === '퇴원' && h.at === d).map(h => h.who)).size, leads: LEADS().filter(l => !['등록', '보류'].includes(l.st)).length, todo: ACTIVE().filter(m => !last[m.id] || last[m.id] < lim).length }; };
  /* 등록된 숫자만으로 만든 요약. 외부 AI로 원생 정보를 보내지 않는다 */
  const dailySummary = (d, F) => { const L = [`${d} 수업 ${F.U.length}개${F.closed ? `(휴강 ${F.closed}개)` : ''}, 출결 대상 ${F.need}명 중 ${F.marked}명 입력.`]; if (F.need > F.marked) L.push(`출결 미입력 ${F.need - F.marked}명을 확인해 주십시오.`); if (F.absent) L.push(`결석 ${F.absent}명: ${F.absNames.slice(0, 5).join(', ')}${F.absNames.length > 5 ? ' 외' : ''}. 보강 일정이 필요한지 확인해 주십시오.`); L.push(`수납 ${won(F.income)}, 미납 잔액 ${won(F.un)}${F.lateN ? `(마감 경과 ${F.lateN}건)` : ''}.`); if (F.newN || F.outN || F.cs) L.push(`입학 ${F.newN}건, 퇴원 ${F.outN}명, 상담 ${F.cs}건.`); if (F.leads) L.push(`처리 중인 신규 문의 ${F.leads}건.`); if (F.todo) L.push(`${CFG().csDays}일 이상 상담하지 않은 재원생 ${F.todo}명.`); return L; };
  VIEWS.crmstat = () => { const tb = UI.crmST || 'day'; return head('학원 현황', '오늘과 이번 달을 숫자로 봅니다') + sampleBar() + tabs('crmST', [['day', '일일 현황'], ['mon', '월별 현황'], ['tch', '강사별']], tb) + (tb === 'mon' ? statMon() : tb === 'tch' ? statTch() : statDay()); };
