  function statMon() { const now = today().slice(0, 7); const P = allPays(); const rows = Array.from({ length: 6 }, (_, i) => addMonth(now, i - 5)).map(ym => { const nw = STUDENTS().filter(m => monthOf(regAt(m)) === ym).length; const out = STUDENTS().filter(m => monthOf((m.crm || {}).outAt) === ym).length; const B = (S.bills || []).filter(b => b.status !== '취소' && (b.month || monthOf(b.due)) === ym); return [fmtYm(ym), headcount(ym) + '명', nw + '명', out + '명', won(B.reduce((a, b) => a + billTotal(b), 0)), won(P.filter(p => monthOf(p.at) === ym).reduce((a, p) => a + p.amt, 0)), won(B.reduce((a, b) => a + billBal(b), 0))]; }); const reasons = {}; STUDENTS().filter(m => (m.crm || {}).outReason).forEach(m => { reasons[m.crm.outReason] = (reasons[m.crm.outReason] || 0) + 1; }); return `<div class="card">${table(['월', '월말 재원', '신규', '퇴원', '청구', '수납', '미납'], rows)}</div><div class="card"><div class="ch"><b>퇴원 사유</b></div>${table(['사유', '인원'], Object.entries(reasons).sort((a, b) => b[1] - a[1]).map(([r, n]) => [esc(r), n + '명']), '퇴원 기록이 없습니다.')}</div>`; }
